def transform(grid):
    """Extend each adjacent diagonal pair of a non-background color both ways."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != background}
    for color in colors:
        points = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for r, c in points:
            for dr, dc in ((1, 1), (1, -1)):
                if (r + dr, c + dc) in points:
                    for sr, sc in ((-dr, -dc), (dr, dc)):
                        rr, cc = r + sr, c + sc
                        while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                            out[rr][cc] = color
                            rr += sr
                            cc += sc
    return out
